module envelope_optimizer #(\n    parameter N = 8,  // Max number of card types\n    parameter K = 4,  // Max envelope types\n    parameter DATA_W = 16,  // Data width for w,h,q\n    parameter RESULT_W = 32  // Result width\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_W-1:0] card_width [N-1:0],\n    input wire [DATA_W-1:0] card_height [N-1:0],\n    input wire [DATA_W-1:0] card_qty [N-1:0],\n    input wire [3:0] num_env_types,  // k (1-4)\n    output reg [RESULT_W-1:0] result,\n    output reg done\n);\n\n// States\nlocalparam [2:0] IDLE = 3'd0;\nlocalparam [2:0] COMPUTE_SUBSET = 3'd1;\nlocalparam [2:0] DP_INIT = 3'd2;\nlocalparam [2:0] DP_COMPUTE = 3'd3;\nlocalparam [2:0] FINISH = 3'd4;\n\nreg [2:0] state;\nreg [2:0] next_state;\n\n// Memory for subset waste calculation (2^N = 256 entries)\nreg [RESULT_W-1:0] subset_waste [0:255];\nreg [7:0] subset_idx;  // Current subset being computed\n\n// DP arrays: dp[mask][t]\nreg [RESULT_W-1:0] dp [0:255];  // Current dp layer (t-1)\nreg [RESULT_W-1:0] next_dp [0:255];  // Next dp layer (t)\n\n// Helper variables\nreg [7:0] mask;\nreg [7:0] submask;\nreg [DATA_W-1:0] max_w, max_h;\nreg [DATA_W*2-1:0] env_area;\nreg [RESULT_W-1:0] sum_qty;\nreg [RESULT_W-1:0] sum_area;\nreg [3:0] t;  // Current envelope type count\nreg [7:0] i, j;\nreg [RESULT_W-1:0] candidate;\n\n// Combinational logic for subset computation\nalways @(*) begin\n    // Calculate max width and height for current subset\n    max_w = 0;\n    max_h = 0;\n    sum_qty = 0;\n    sum_area = 0;\n    \n    for (i = 0; i < N; i = i + 1) begin\n        if (subset_idx[i]) begin\n            if (card_width[i] > max_w) max_w = card_width[i];\n            if (card_height[i] > max_h) max_h = card_height[i];\n            sum_qty = sum_qty + card_qty[i];\n            sum_area = sum_area + (card_qty[i] * (card_width[i] * card_height[i]));\n        end\n    end\n    \n    env_area = max_w * max_h;\nend\n\n// Sequential state transitions\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        subset_idx <= 0;\n        t <= 0;\n        done <= 0;\n        result <= 0;\n    end else begin\n        state <= next_state;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    subset_idx <= 1;  // Start from subset {0} (but we'll process from 0)\n                    t <= 1;\n                    done <= 0;\n                end\n            end\n            \n            COMPUTE_SUBSET: begin\n                // Calculate waste for current subset\n                if (sum_qty > 0) begin\n                    subset_waste[subset_idx] <= (env_area * sum_qty) - sum_area;\n                end else begin\n                    subset_waste[subset_idx] <= 0;\n                end\n                \n                if (subset_idx == 255) begin\n                    subset_idx <= 0;\n                end else begin\n                    subset_idx <= subset_idx + 1;\n                end\n            end\n            \n            DP_INIT: begin\n                // Initialize dp[0][*] = 0, dp[mask][0] = INF for mask != 0\n                if (subset_idx == 0) begin\n                    dp[0] <= 0;\n                    subset_idx <= 1;\n                end else if (subset_idx < 255) begin\n                    dp[subset_idx] <= 32'h7FFFFFFF;  // INF\n                    subset_idx <= subset_idx + 1;\n                end else begin\n                    dp[255] <= 32'h7FFFFFFF;\n                    subset_idx <= 0;\n                    t <= 1;\n                end\n            end\n            \n            DP_COMPUTE: begin\n                if (t <= num_env_types) begin\n                    // For each mask, compute min over submask\n                    if (mask == 0) begin\n                        mask <= 1;\n                        next_dp[0] <= dp[0];  // dp[0][t] = dp[0][t-1] = 0\n                    end else if (mask < 255) begin\n                        // Compute for current mask\n                        if (submask == 0) begin\n                            // Initialize with large value\n                            next_dp[mask] <= 32'h7FFFFFFF;\n                            submask <= mask;\n                        end else if (submask > 0) begin\n                            // submask is subset of mask\n                            if (subset_waste[submask] < 32'h7FFFFFFF && dp[mask ^ submask] < 32'h7FFFFFFF) begin\n                                candidate <= subset_waste[submask] + dp[mask ^ submask];\n                            end else begin\n                                candidate <= 32'h7FFFFFFF;\n                            end\n                            \n                            if (submask == mask) begin\n                                submask <= 0;\n                                mask <= mask + 1;\n                            end else begin\n                                // Find next submask using trick: (submask - 1) & mask\n                                submask <= (submask - 1) & mask;\n                            end\n                        end else begin\n                            // Done with this mask\n                            if (next_dp[mask] > candidate) begin\n                                next_dp[mask] <= candidate;\n                            end\n                        end\n                    end else begin\n                        // All masks computed for current t\n                        // Copy next_dp to dp\n                        if (subset_idx < 255) begin\n                            dp[subset_idx] <= next_dp[subset_idx];\n                            subset_idx <= subset_idx + 1;\n                        end else begin\n                            dp[255] <= next_dp[255];\n                            subset_idx <= 0;\n                            mask <= 0;\n                            submask <= 0;\n                            t <= t + 1;\n                        end\n                    end\n                end else begin\n                    // Finished all DP iterations\n                    result <= dp[255];\n                    done <= 1;\n                end\n            end\n            \n            FINISH: begin\n                done <= 0;\n            end\n        endcase\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: begin\n            if (start) next_state = COMPUTE_SUBSET;\n        end\n        \n        COMPUTE_SUBSET: begin\n            if (subset_idx == 255) next_state = DP_INIT;\n        end\n        \n        DP_INIT: begin\n            if (subset_idx == 255 && t == 1) next_state = DP_COMPUTE;\n        end\n        \n        DP_COMPUTE: begin\n            if (t > num_env_types) next_state = FINISH;\n        end\n        \n        FINISH: begin\n            if (!done) next_state = IDLE;\n        end\n        \n        default: next_state = IDLE;\n    endcase\nend\n\nendmodule